"""Offline shared WebGL extrusion preview. No external scripts or geometry services."""
MODEL_HTML=r'''<div class="actions"><button type="button" class="secondary" id="model-open" onclick="loadModelPreview()" disabled>3D-Druckwegvorschau laden</button><button type="button" class="quiet" id="model-cancel" onclick="resetModelPreview('3D-Laden abgebrochen.')" hidden>Laden abbrechen</button></div><p id="model-status" class="muted small" role="status"></p><div id="model-view" class="viewer-stage" hidden><canvas id="model-canvas" class="model-canvas" tabindex="0" aria-label="Interaktive 3D-Druckwegvorschau; Pfeiltasten drehen, Plus und Minus zoomen"></canvas><div class="actions"><button type="button" class="quiet" onclick="modelViewer?.zoom(1.25)">Vergrößern +</button><button type="button" class="quiet" onclick="modelViewer?.zoom(.8)">Verkleinern −</button><button type="button" class="quiet" onclick="modelViewer?.reset()">Ansicht zurücksetzen</button></div><div id="model-tools"></div><p class="muted small">Ziehen: drehen · Mausrad / zwei Finger: zoomen · Pfeiltasten / + / − ebenfalls möglich.</p><p id="model-warnings" class="muted small"></p></div><style>.model-canvas{display:block;width:100%;height:360px;background:#10171f;border:1px solid var(--line);border-radius:12px;touch-action:none;cursor:grab}.model-canvas:active{cursor:grabbing}@media(max-width:600px){ .model-canvas{height:280px}}.viewer-stage:fullscreen{background:var(--surface);padding:16px;overflow:auto}.viewer-stage:fullscreen canvas{height:75vh}.viewer-tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.viewer-tools label{min-width:140px}.viewer-tools input{width:100%}</style>'''

MODEL_JS=r'''
let modelLoad=null,modelGeneration=0,modelPlate=null,modelViewer=null;
function resetModelPreview(message=''){if(modelLoad)cancelDetailLoad(modelLoad);modelLoad=null;modelGeneration++;modelPlate=null;modelViewer?.dispose();modelViewer=null;byId('model-view').hidden=true;byId('model-cancel').hidden=true;byId('model-status').textContent=message;byId('model-open').textContent='3D-Druckwegvorschau laden';byId('model-open').disabled=!detailReady;byId('start-review-button').disabled=startingPrint||!detailReady||!detailContext||!!detailFile?.blocked;}
function syncModelPlate(index){if(modelPlate!==null&&String(modelPlate)!==String(index))resetModelPreview();byId('model-open').disabled=!detailReady||!!modelLoad||!!modelViewer}
async function loadModelPreview(){if(!detailReady||startingPrint||modelLoad)return;resetModelPreview();invalidatePrintReview();const generation=detailGeneration,version=++modelGeneration,plate=Number(byId('detail-plate').value),load={file:detailFile.token,viewer:'3d-'+(globalThis.crypto?.randomUUID?.()||(Date.now()+'-'+Math.random())),complete:false,ticket:null};modelLoad=load;modelPlate=plate;byId('model-open').disabled=true;byId('model-cancel').hidden=false;byId('start-review-button').disabled=true;byId('model-status').textContent='3D-Datei wird im Hintergrund gelesen …';
try{let data=await storageJSON('/storage/model',{method:'POST',body:new URLSearchParams({file:load.file,plate,viewer:load.viewer,csrf_token:csrf})});load.ticket=data.ticket;if(version!==modelGeneration||generation!==detailGeneration){cancelDetailLoad(load);return}while(data.state==='loading'){byId('model-status').textContent=data.phase==='waiting_status'?'Warte auf neue Leerlaufbestätigung …':data.phase==='building'?'3D-Druckwege werden aufbereitet …':'3D-Datei wird gelesen: '+sizeLabel(data.received||0)+' / '+sizeLabel(data.total||detailFile.size);await new Promise(r=>setTimeout(r,300));if(version!==modelGeneration||generation!==detailGeneration)return;data=await storageJSON('/api/storage/details?ticket='+encodeURIComponent(load.ticket))}load.complete=true;if(version!==modelGeneration||generation!==detailGeneration)return;if(data.state!=='done'||!data.model)throw Error(data.error||'3D-Laden abgebrochen.');byId('model-view').hidden=false;modelViewer=createModelViewer(data.model,byId('model-canvas'));mountModelTools(modelViewer,byId('model-tools'));byId('model-warnings').textContent=data.model.warnings.join(' ');byId('model-status').textContent='Modellplatte '+plate+' · '+data.model.segments.toLocaleString('de-DE')+' dargestellte Druckwegsegmente';byId('model-open').textContent='3D-Druckwegvorschau geladen';}
catch(e){cancelDetailLoad(load);if(version===modelGeneration&&generation===detailGeneration){byId('model-status').textContent=e.message;byId('model-view').hidden=true}}
finally{if(version===modelGeneration&&generation===detailGeneration){modelLoad=null;byId('model-cancel').hidden=true;byId('model-open').disabled=!!modelViewer||!detailReady;byId('start-review-button').disabled=!detailReady||!detailContext||!!detailFile?.blocked}}
}
'''

from .model_renderer import RENDERER_JS
MODEL_JS += RENDERER_JS

MODEL_JS += r'''
let previewModelFile=null,previewModelViewer=null,previewModelLoad=null,previewModelGeneration=0,previewModelMetadata=null;
function resetPreviewModel(){previewModelGeneration++;cancelDetailLoad(previewModelLoad);previewModelLoad=null;previewModelViewer?.dispose();previewModelViewer=null;previewModelFile=null;previewModelMetadata=null;byId('preview-3d-stage').hidden=true;byId('preview-plate-label').hidden=true;byId('preview-3d-status').textContent='';byId('preview-3d-open').disabled=false;byId('preview-image').hidden=false;}
async function loadPreviewModel(changed=false){if(!previewModelFile)return;cancelDetailLoad(previewModelLoad);previewModelViewer?.dispose();previewModelViewer=null;byId('preview-3d-stage').hidden=true;const version=++previewModelGeneration,file=previewModelFile;byId('preview-3d-open').disabled=true;byId('preview-3d-status').textContent='3D-Vorschau wird im Hintergrund vorbereitet …';
 const requestModel=async(path,plate)=>{const load={file:file.token,viewer:'preview-'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random()),complete:false,ticket:null};previewModelLoad=load;let d=await storageJSON(path,{method:'POST',body:new URLSearchParams({file:load.file,viewer:load.viewer,csrf_token:csrf,...(plate==null?{}:{plate})})});load.ticket=d.ticket;if(version!==previewModelGeneration){cancelDetailLoad(load);return null}while(d.state==='loading'){byId('preview-3d-status').textContent=d.phase==='waiting_status'?'Warte auf neue Leerlaufbestätigung …':d.phase==='building'?'Druckbahnen werden aufbereitet …':'Datei wird gelesen: '+sizeLabel(d.received||0)+' / '+sizeLabel(d.total||file.size);await new Promise(r=>setTimeout(r,300));if(version!==previewModelGeneration)return null;d=await storageJSON('/api/storage/details?ticket='+encodeURIComponent(load.ticket));if(version!==previewModelGeneration)return null}load.complete=true;if(d.state!=='done')throw Error(d.error||'3D-Laden abgebrochen.');return d;};
 try{if(!previewModelMetadata){const result=await requestModel('/storage/details');if(!result)return;previewModelMetadata=result.metadata;const select=byId('preview-plate');select.replaceChildren();for(const p of previewModelMetadata.plates)select.add(new Option('Modellplatte '+p.index+(p.name?' · '+p.name:''),p.index));byId('preview-plate-label').hidden=previewModelMetadata.plates.length<2;}
 const selected=previewModelMetadata.plates.find(p=>String(p.index)===byId('preview-plate').value);if(selected?.preview)byId('preview-image').src=selected.preview;
 const result=await requestModel('/storage/model',byId('preview-plate').value);if(!result||version!==previewModelGeneration)return;byId('preview-3d-stage').hidden=false;byId('preview-image').hidden=true;previewModelViewer=createModelViewer(result.model,byId('preview-3d-canvas'));mountModelTools(previewModelViewer,byId('preview-3d-tools'));byId('preview-3d-status').textContent=result.model.segments.toLocaleString('de-DE')+' Druckbahnsegmente. Ziehen: drehen · Mausrad / zwei Finger: zoomen. '+result.model.warnings.join(' ');
 }catch(e){if(version===previewModelGeneration){cancelDetailLoad(previewModelLoad);byId('preview-3d-status').textContent=e.message;byId('preview-image').hidden=false;}}
 finally{if(version===previewModelGeneration){previewModelLoad=null;byId('preview-3d-open').disabled=false;byId('preview-3d-open').textContent='3D-Ansicht neu laden';}}
}
window.addEventListener('pagehide',()=>resetPreviewModel());
'''
